window.processPatrolSessionSnapshot =
function(sessionId, pointSnap, staffMember){

  if(!sessionId || !pointSnap){
    return;
  }

  // ==========================================================
  // 🔒 NORMALIZE SESSION ID
  // ==========================================================

  sessionId =
    String(sessionId || "").trim();

  if(!sessionId){
    return;
  }


  // ==========================================================
  // 1. CENTRAL SESSION CACHE
  // ----------------------------------------------------------
  // Firestore document changes are applied incrementally.
  // No second Firestore read is required.
  // ==========================================================

  window.sessionPointCache ??=
    Object.create(null);

  window.sessionPointCache[sessionId] ??=
    Object.create(null);

  const pointCache =
    window.sessionPointCache[sessionId];

  const newPoints = [];


  // ==========================================================
  // 🔥 READ CHANGES ONCE
  // ----------------------------------------------------------
  // IMPORTANT:
  // Do not repeatedly call pointSnap.docChanges().
  // ==========================================================

  const changes =
    pointSnap.docChanges();


  // ==========================================================
  // 🔥 APPLY FIRESTORE DOCUMENT CHANGES
  // ==========================================================

  changes.forEach(
    change => {

      const pointId =
        change.doc.id;


      // ======================================================
      // ❌ REMOVED POINT
      // ======================================================

      if(change.type === "removed"){

        delete pointCache[pointId];

        return;
      }


      // ======================================================
      // 📦 POINT DATA
      // ======================================================

      const data =
        change.doc.data();

      if(!data){
        return;
      }


      // ======================================================
      // 📍 GPS VALIDATION
      // ======================================================

      const lat =
        Number(data.lat);

      const lon =
        Number(data.lon);

      if(
        !Number.isFinite(lat) ||
        !Number.isFinite(lon)
      ){
        return;
      }


      // ======================================================
      // 🕒 NORMALIZE POINT TIME
      // ======================================================

      const rawPointTime =
        data.time ??
        data.timestamp ??
        "";

      let pointTime =
        0;


      if(
        typeof rawPointTime ===
        "string"
      ){

        const parsed =
          Date.parse(rawPointTime);

        if(
          Number.isFinite(parsed)
        ){
          pointTime =
            parsed;
        }

      }
      else if(
        typeof rawPointTime?.toDate ===
        "function"
      ){

        try{

          pointTime =
            rawPointTime
              .toDate()
              .getTime();

        }
        catch(err){

          pointTime =
            0;
        }

      }
      else if(
        Number.isFinite(
          Number(rawPointTime)
        ) &&
        Number(rawPointTime) > 0
      ){

        pointTime =
          Number(rawPointTime);
      }


      // ======================================================
      // 📦 CENTRAL NORMALIZED POINT
      // ======================================================

      const cachedPoint = {

        ...data,

        id:
          pointId,

        lat:
          lat,

        lon:
          lon,

        time:
          pointTime,

        breakTrack:
          data.breakTrack === true,

        sessionId:
          String(
            data.sessionId ||
            sessionId
          ).trim()

      };


      // ======================================================
      // 💾 SAVE INTO CENTRAL SESSION CACHE
      // ======================================================

      pointCache[pointId] =
        cachedPoint;


      // ======================================================
      // 🔥 ONLY NEW POINTS → DOWNSTREAM CONSUMERS
      // ======================================================

      if(
        change.type === "added"
      ){

        newPoints.push(
          cachedPoint
        );

      }

    }
  );


  // ==========================================================
  // 2. CENTRAL MOVEMENT / DISTANCE / TELEPORT PROCESSING
  // ==========================================================
  //
  // This state is session-owned.
  //
  // DO NOT key it by cleanName.
  // ==========================================================

  window.lastPatrolPoint ??=
    Object.create(null);

  let previousPoint =
    window.lastPatrolPoint[sessionId] ||
    null;


  // ==========================================================
  // 🔥 CHRONOLOGICAL ORDER
  // ----------------------------------------------------------
  // Only sort the NEW batch.
  // Never sort the complete session cache.
  // ==========================================================

  newPoints.sort(
    (a, b) =>
      Number(a.time || 0) -
      Number(b.time || 0)
  );


  // ==========================================================
  // 🔥 VALID TRACK POINTS
  // ----------------------------------------------------------
  // Used for the visual track consumer.
  // ==========================================================

  const validPoints = [];


  for(
    const curr of newPoints
  ){

    if(!curr){
      continue;
    }


    // ========================================================
    // FIRST POINT OF SESSION
    // ========================================================

    if(!previousPoint){

      validPoints.push(
        curr
      );

      previousPoint =
        curr;

      continue;
    }


    // ========================================================
    // INVALID GPS
    // ========================================================

    if(
      !Number.isFinite(
        previousPoint.lat
      ) ||
      !Number.isFinite(
        previousPoint.lon
      ) ||
      !Number.isFinite(
        curr.lat
      ) ||
      !Number.isFinite(
        curr.lon
      )
    ){

      previousPoint =
        curr;

      continue;
    }


    // ========================================================
    // 📏 DISTANCE METERS
    // ========================================================

    let dist =
      0;

    try{

      if(
        typeof map !== "undefined" &&
        typeof map.distance ===
        "function"
      ){

        dist =
          map.distance(
            [
              previousPoint.lat,
              previousPoint.lon
            ],
            [
              curr.lat,
              curr.lon
            ]
          );

      }

    }
    catch(err){

      dist =
        0;
    }


    // ========================================================
    // ⏱ TIME DIFFERENCE
    // ========================================================

    let timeDiffSec =
      1;

    try{

      const prevTime =
        Number(
          previousPoint.time ||
          previousPoint.timestamp ||
          0
        );

      const currTime =
        Number(
          curr.time ||
          curr.timestamp ||
          0
        );

      if(
        prevTime > 0 &&
        currTime > prevTime
      ){

        timeDiffSec =
          Math.max(
            1,
            (
              currTime -
              prevTime
            ) / 1000
          );

      }

    }
    catch(err){}


    // ========================================================
    // 🚀 SPEED
    // ========================================================

    const speedKmh =
      (
        dist /
        timeDiffSec
      ) * 3.6;


    // ========================================================
    // 🚨 TELEPORT / INVALID MOVEMENT
    // ========================================================

    const invalidMovement =
      dist > 500 ||
      speedKmh > 120 ||
      !Number.isFinite(dist) ||
      !Number.isFinite(speedKmh);


    if(invalidMovement){

      console.warn(
        "⚠ TELEPORT BLOCKED",
        {
          sessionId:
            sessionId,

          distance:
            Math.round(dist),

          speed:
            Math.round(speedKmh),

          from:
            [
              previousPoint.lat,
              previousPoint.lon
            ],

          to:
            [
              curr.lat,
              curr.lon
            ]
        }
      );


      // ======================================================
      // OPTIONAL VISUAL RECONNECT
      // ======================================================

      try{

        if(
          typeof drawReconnectLine ===
          "function"
        ){

          drawReconnectLine(
            previousPoint,
            curr
          );

        }

      }
      catch(err){}


      // ======================================================
      // IMPORTANT:
      // Do NOT add teleport segment to valid track.
      // But advance the last known GPS point so the next
      // legitimate point starts from the current location.
      // ======================================================

      previousPoint =
        curr;

      continue;
    }


    // ========================================================
    // ✅ VALID MOVEMENT
    // ========================================================

    validPoints.push(
      curr
    );


    // ========================================================
    // 🔥 ADVANCE SESSION LAST POINT
    // ========================================================

    previousPoint =
      curr;

  }


  // ==========================================================
  // 3. SAVE SESSION LAST POINT
  // ==========================================================

  window.lastPatrolPoint[sessionId] =
    previousPoint;


  // ==========================================================
  // 4. STAFF IDENTITY + POINT COUNT
  // ==========================================================

  const staffName =
    typeof cleanName ===
    "function"

      ? cleanName(
          staffMember?.cleanName ||
          staffMember?.name ||
          ""
        )

      : String(
          staffMember?.cleanName ||
          staffMember?.name ||
          ""
        ).trim();


  if(staffName){

    window.trackPointCount ??=
      Object.create(null);

    window.trackPointCount[
      staffName
    ] =
      Object.keys(
        pointCache
      ).length;

  }


// ==========================================================
// 5. LIVE MARKER CONSUMER
// ----------------------------------------------------------
// Uses the central session cache.
//
// IMPORTANT:
// - No Firestore read here.
// - No second patrol listener.
// - The marker helper resolves the authoritative latest
//   point from sessionPointCache.
// ==========================================================

if(
  staffMember &&
  typeof window.updateLiveMarkerFromPatrolPoint ===
  "function"
){

  window.updateLiveMarkerFromPatrolPoint(
    staffMember,
    null,
    sessionId
  );

}
  // ==========================================================
  // 6. TRACK RENDERER
  // ----------------------------------------------------------
  // RENDER ONLY.
  //
  // IMPORTANT:
  // validPoints contains only movement-valid points.
  // The renderer does not create a Firestore listener.
  // ==========================================================

  if(
    staffMember &&
    typeof window.appendNewPatrolPointsToTrack ===
    "function" &&
    validPoints.length > 0
  ){

    const currentUserName =
      typeof cleanName ===
      "function"

        ? cleanName(
            window.userProfile?.cleanName ||
            window.userProfile?.name ||
            ""
          )

        : String(
            window.userProfile?.cleanName ||
            window.userProfile?.name ||
            ""
          ).trim();


    const selectedStaffName =
      typeof cleanName ===
      "function"

        ? cleanName(
            window.staffTrackState?.selectedStaff ||
            ""
          )

        : String(
            window.staffTrackState?.selectedStaff ||
            ""
          ).trim();


    const bulkEnabled =
      window.staffTrackState?.bulkEnabled ===
      true;


    if(
      staffName === currentUserName ||
      (
        !bulkEnabled &&
        staffName === selectedStaffName
      ) ||
      bulkEnabled
    ){

      window.appendNewPatrolPointsToTrack(
        staffMember,
        sessionId,
        validPoints
      );

    }

  }


  // ==========================================================
  // 7. ANALYTICS CONSUMER
  // ----------------------------------------------------------
  // IMPORTANT:
  // Analytics is NOT another Firestore listener.
  //
  // It receives the already-received NEW POINTS from this
  // session owner.
  //
  // Keep analytics on newPoints rather than validPoints so
  // its existing session/grid traversal semantics remain
  // unchanged.
  // ==========================================================

  if(
    staffMember &&
    typeof window.processPatrolAnalyticsSnapshot ===
    "function" &&
    newPoints.length > 0
  ){

    window.processPatrolAnalyticsSnapshot(
      newPoints,
      staffMember,
      sessionId
    );

  }


  // ==========================================================
  // 8. IDB PERSISTENCE
  // ----------------------------------------------------------
  // One debounce timer PER SESSION.
  // Prevents session A from cancelling session B's save.
  // ==========================================================

  window.__patrolPointIDBSaveTimers ??=
    Object.create(null);


  if(
    typeof window.savePatrolPointsToIDB ===
    "function"
  ){

    clearTimeout(
      window.__patrolPointIDBSaveTimers[
        sessionId
      ]
    );


    window.__patrolPointIDBSaveTimers[
      sessionId
    ] =
      setTimeout(
        function(){

          window.savePatrolPointsToIDB(
            sessionId,
            window.sessionPointCache[
              sessionId
            ]
          );

        },
        1000
      );

  }

}

