          ? pointDoc.data()
          : null;

      if(!rawPoint){
        return;
      }

      const point = {
        ...rawPoint,

        id:
          String(
            rawPoint.id ||
            rawPoint.pointId ||
            pointDoc.id ||
            ""
          ).trim(),

        sessionId:
          String(
            rawPoint.sessionId ||
            sessionId
          ).trim()
      };

      const lat =
        Number(point.lat);

      const lon =
        Number(point.lon);

      if(
        !Number.isFinite(lat) ||
        !Number.isFinite(lon) ||
        lat === 0 ||
        lon === 0
      ){
        return;
      }

      // Ensure the existing marker path can find this point
      // through its authoritative cache helper.
      window.sessionPointCache ??=
        Object.create(null);

