window.updateLiveMarkerFromPatrolPoint =
function(staff, point, originatingSessionId){

    try{

        // ========================================================
        // 1. BASIC VALIDATION
        // ========================================================

        if(!staff){
            return;
        }


        // ========================================================
        // 2. CANONICAL STAFF NAME
        // ========================================================

        const staffName =
            cleanName(
                staff.cleanName ||
                staff.name ||
                point?.cleanName ||
                point?.name ||
                ""
            );


        if(!staffName){
            return;
        }


        // ========================================================
        // 3. DUTY AUTHORIZATION
        // --------------------------------------------------------
        // Marker/popup is ONLY for dutyActive === true.
        // ========================================================

        if(staff.dutyActive !== true){

            const oldMarker =
                window.staffMarkers?.[staffName];

            if(oldMarker){

                try{

                    if(
                        typeof oldMarker.isPopupOpen ===
                        "function" &&
                        oldMarker.isPopupOpen()
                    ){
                        oldMarker.closePopup();
                    }

                }catch(e){}

                try{
                    staffLayer.removeLayer(oldMarker);
                }catch(e){}

                delete window.staffMarkers[staffName];
            }

            return;
        }


        // ========================================================
        // 4. VISIBILITY AUTHORIZATION
        // --------------------------------------------------------
        // Do NOT recreate/keep a marker merely because staff is
        // duty-active. Existing visibility rules remain authoritative.
        // ========================================================

        const visibleStaff =
            window.visibleStaffCache?.[staffName];


        if(!visibleStaff){

            const oldMarker =
                window.staffMarkers?.[staffName];

            if(oldMarker){

                try{

                    if(
                        typeof oldMarker.isPopupOpen ===
                        "function" &&
                        oldMarker.isPopupOpen()
                    ){
                        oldMarker.closePopup();
                    }

                }catch(e){}

                try{
                    staffLayer.removeLayer(oldMarker);
                }catch(e){}

                delete window.staffMarkers[staffName];
            }

            return;
        }


        if(visibleStaff.dutyActive !== true){

            const oldMarker =
                window.staffMarkers?.[staffName];

            if(oldMarker){

                try{
                    oldMarker.closePopup();
                }catch(e){}

                try{
                    staffLayer.removeLayer(oldMarker);
                }catch(e){}

                delete window.staffMarkers[staffName];
            }

            return;
        }


        // ========================================================
        // 5. SESSION OWNERSHIP
        // --------------------------------------------------------
        // Session identity comes from the authorized staff/session,
        // NOT from an unrelated incoming patrol point.
        // ========================================================

        let sessionId =
            String(
                visibleStaff.sessionId ||
                staff.sessionId ||
                window.activeSessionMap?.[staffName] ||
                ""
            ).trim();


        if(!sessionId){
            return;
        }


        // ========================================================
        // 6. AUTHORITATIVE LATEST POINT
        // --------------------------------------------------------
        // ALWAYS re-read the session cache.
        //
        // This prevents:
        //
        // point 97
        //   ↓
        // point 98
        //   ↓
