            );


        let lon =
            Number(
                latestPoint.lon
            );


        if(
            !Number.isFinite(lat) ||
            !Number.isFinite(lon) ||
            lat === 0 ||
            lon === 0
        ){
            return;
        }


        // ========================================================
        // 9. POINT ID
        // ========================================================

        let pointId =
            String(
                latestPoint.id ??
                latestPoint.pointId ??
                ""
            ).trim();


        latestPoint.id =
            pointId;


        // ========================================================
        // 10. AUTHORITATIVE STAFF → POINT STATE
        // ========================================================

        window.latestPatrolPointByStaff ??=
            Object.create(null);


        window.latestPatrolPointByStaff[
            staffName
        ] =
            latestPoint;


        window.latestPatrolPointIdentity ??=
            Object.create(null);


        window.latestPatrolPointIdentity[
            staffName
        ] = {

            sessionId:
                sessionId,

            pointId:
                pointId,

            lat:
                lat,

            lon:
                lon,

            time:
                typeof getPointTime === "function"
                    ? Number(
                        getPointTime(latestPoint)
                      ) || 0
                    : Number(
                        latestPoint.time || 0
                      )
        };


        // ========================================================
        // 11. POINT COUNT
        // --------------------------------------------------------
        // Prefer the authoritative patrol point count when present.
        // Otherwise derive from this session cache.
        // ========================================================

        window.trackPointCount ??=
            Object.create(null);


        const cachedPointCount = window.StaffRendering ? window.StaffRendering.count(sessionId) :
            Object.keys(window.sessionPointCache?.[sessionId] || {}).length;


        const rawPointCount =
            Number(
                latestPoint.patrolPointCount
            );


        let calculatedPointCount =
            Number.isFinite(rawPointCount) &&
            rawPointCount >= 0
                ? rawPointCount
                : cachedPointCount;


        window.trackPointCount[
            staffName
        ] =
            calculatedPointCount;


        // ========================================================
        // 12. CURRENT USER GPS BRIDGE
        // ========================================================

        const currentUserName =
            cleanName(
                window.userProfile?.cleanName ||
                window.userProfile?.name ||
                ""
            );


        if(
            staffName === currentUserName
        ){

            window.latestGps = {

                lat:
                    lat,

                lng:
                    lon,

                accuracy:
                    Number.isFinite(
                        Number(
                            latestPoint.accuracy
                        )
                    )
                        ? Number(
                            latestPoint.accuracy
                          )
                        : null,

                speed:
                    Number.isFinite(
                        Number(
                            latestPoint.speed
                        )
                    )
                        ? Number(
                            latestPoint.speed
                          )
                        : null,

                heading:
                    Number.isFinite(
                        Number(
                            latestPoint.heading
                        )
                    )
                        ? Number(
                            latestPoint.heading
                          )
                        : null,

                time:
                    typeof getPointTime ===
                    "function"
                        ? getPointTime(
                            latestPoint
                          )
                        : Number(
                            latestPoint.time ||
                            Date.now()
                          )
            };

        }


        // ========================================================
        // 13. FIND EXISTING MARKER
        // ========================================================

        let marker = window.staffMarkers?.[staffName];

        if(!marker){
            // Captured listener metadata cannot authorize missing-marker creation.
            const currentStaff = window.visibleStaffCache?.[staffName];
            const originSession = String(originatingSessionId || "").trim();
            if(!currentStaff || currentStaff.dutyActive !== true ||
               cleanName(currentStaff.cleanName || currentStaff.name || "") !== staffName ||
               String(currentStaff.cleanName || "").trim() !== staffName ||
               String(currentStaff.sessionId || "").trim() !== sessionId ||
               String(staff.sessionId || "").trim() !== sessionId ||
               !originSession || originSession !== sessionId){
                return;
            }

            // Match the existing render pass's five-decimal overlap grouping.
            let markerLat = lat;
            let markerLon = lon;
            const coordinateKey = lat.toFixed(5) + "," + lon.toFixed(5);
            let overlapCount = 0;
            if (window.StaffRendering) overlapCount = window.StaffRendering.overlapCount(coordinateKey);
            else {
            for(const candidate of Object.values(window.visibleStaffCache || {})){
                if(!candidate || candidate.dutyActive !== true) continue;
                const candidateName = cleanName(candidate.cleanName || candidate.name || "");
                if(!candidateName) continue;
                const candidateSession = String(candidate.sessionId ||
                    window.activeSessionMap?.[candidateName] || "").trim();
                if(!candidateSession) continue;
                const candidatePoint = window.getLatestPatrolPointForSession(candidateSession);
                if(!candidatePoint || String(candidatePoint.sessionId || candidateSession).trim() !== candidateSession) continue;
                const candidateLat = Number(candidatePoint.lat);
                const candidateLon = Number(candidatePoint.lon);
                if(!Number.isFinite(candidateLat) || !Number.isFinite(candidateLon) ||
                   candidateLat === 0 || candidateLon === 0) continue;
                if(candidateLat.toFixed(5) + "," + candidateLon.toFixed(5) === coordinateKey) overlapCount++;
            }
            }
            if(overlapCount > 1){
                let hash = 0;
                const stableId = String(currentStaff.cleanName || "");
                for(let i = 0; i < stableId.length; i++) hash += stableId.charCodeAt(i);
                const angle = (hash % 360) * Math.PI / 180;
                markerLat += Math.cos(angle) * 0.00003;
                markerLon += Math.sin(angle) * 0.00003;
            }
            marker = window.ensureLiveStaffMarker(
                currentStaff, latestPoint, sessionId, markerLat, markerLon
            ).marker;
            if(!marker) return;
        }


        // ========================================================
        // 14. STORE AUTHORITATIVE IDENTITY ON MARKER
        // ========================================================

        marker.__patrolPointIdentity = {

            sessionId:
                sessionId,

            pointId:
                pointId,

            lat:
                lat,

            lon:
                lon,

            time:
                typeof getPointTime ===
                "function"
                    ? Number(
                        getPointTime(
                            latestPoint
                        )
                      ) || 0
                    : Number(
                        latestPoint.time || 0
                      )

        };


        // ========================================================
        // 15. MOVE MARKER
        // ========================================================

        window.StaffPopup.setPosition(marker, lat, lon);
        if (window.StaffRendering) { window.StaffRendering.refresh(marker); return; }


        // ========================================================
        // 16. POPUP REFRESH FUNCTION
        // --------------------------------------------------------
        // Same existing popup fields.
        //
        // Only live values are changed:
        // GPS
        // speed
        // distance
        // patrol points
        // last GPS
        // current GIS
        // Navigate coordinates
        //
        // The popup HTML/layout itself is NOT redesigned.
        // ========================================================

        const refreshPopup =
            function(){

                try{

                    // =================================================
                    // AUTHORITATIVE LATEST-POINT RE-RESOLUTION
                    // -------------------------------------------------
                    // Every popup refresh re-checks the current
                    // visibility/session state and reads the latest
                    // point from the authoritative session cache.
                    //
                    // This prevents a stale closure from showing
                    // an older patrol point.
                    // =================================================

                    const currentStaff =
                        window.visibleStaffCache?.[staffName];


                    if(
                        !currentStaff ||
                        currentStaff.dutyActive !== true
                    ){

                        try{
                            marker.closePopup();
                        }catch(e){}

                        return;
                    }


                    const currentSessionId =
                        String(
                            currentStaff.sessionId ||
                            window.activeSessionMap?.[staffName] ||
                            sessionId ||
                            ""
                        ).trim();


                    if(!currentSessionId){
                        return;
                    }


                    const currentLatestPoint =
                        typeof window.getLatestPatrolPointForSession ===
                        "function"
                            ? window.getLatestPatrolPointForSession(
                                currentSessionId
                              )
                            : null;


                    if(!currentLatestPoint){
                        return;
                    }


                    const currentLatestSessionId =
                        String(
                            currentLatestPoint.sessionId ||
                            currentSessionId
                        ).trim();


                    if(
                        currentLatestSessionId &&
                        currentLatestSessionId !== currentSessionId
                    ){
                        return;
                    }


                    const currentLat =
                        Number(
                            currentLatestPoint.lat
                        );


                    const currentLon =
                        Number(
                            currentLatestPoint.lon
                        );


                    if(
                        !Number.isFinite(currentLat) ||
                        !Number.isFinite(currentLon) ||
                        currentLat === 0 ||
                        currentLon === 0
                    ){
                        return;
                    }


                    sessionId =
                        currentSessionId;


                    latestPoint =
                        currentLatestPoint;


                    lat =
                        currentLat;


                    lon =
                        currentLon;


                    pointId =
                        String(
                            currentLatestPoint.id ??
                            currentLatestPoint.pointId ??
                            ""
                        ).trim();


                    const currentRawPointCount =
                        Number(
                            currentLatestPoint.patrolPointCount
                        );


                    const currentCachedPointCount =
                        Object.keys(
                            window.sessionPointCache?.[
                                currentSessionId
                            ] || {}
                        ).length;


                    calculatedPointCount =
                        Number.isFinite(
                            currentRawPointCount
                        ) &&
                        currentRawPointCount >= 0
                            ? currentRawPointCount
                            : currentCachedPointCount;


                    window.StaffPopup.setPosition(marker, lat, lon);


                    // =================================================
                    // POPUP
                    // =================================================

                    const popup =
                        marker.getPopup?.();


                    const popupElement =
                        popup?.getElement();


                    if(!popupElement){
                        return;
                    }


                    const popupKey =
                        encodeURIComponent(
                            staffName
                        );


                    // =================================================
                    // GPS
                    // =================================================

                    const gpsElement =
    popupElement.querySelector(
        "#" +
        CSS.escape(
            "staffGps_" + staffName
        )
    );

                    if(gpsElement){

                        gpsElement.textContent =
                            lat.toFixed(6) +
                            ", " +
                            lon.toFixed(6);

                    }


                    // =================================================
                    // SPEED
                    // =================================================

                   const speedElement =
    popupElement.querySelector(
        "#" +
        CSS.escape(
            "staffSpeed_" + staffName
        )
    );


                    if(speedElement){

                        let speed =
                            Number(
                                latestPoint.speed
                            );


                        if(
                            !Number.isFinite(speed) ||
                            speed < 0
                        ){
                            speed = 0;
                        }


                        speedElement.textContent =
                            speed < 1
                                ? "Stationary"
                                : speed.toFixed(1) +
                                  " km/h";

                    }


                    // =================================================
                    // DISTANCE
                    // =================================================

                   const distanceElement =
    popupElement.querySelector(
        "#" +
        CSS.escape(
            "staffDistance_" + staffName
        )
    );


                    if(distanceElement){

                        let distanceKm =
                            Number(
                                latestPoint.distanceCoveredKm
                            );


                        if(
                            !Number.isFinite(
                                distanceKm
                            )
                        ){

                            const distanceMeters =
                                Number(
                                    latestPoint.distanceCoveredMeters
                                );


                            distanceKm =
                                Number.isFinite(
                                    distanceMeters
                                )
                                    ? distanceMeters / 1000
                                    : 0;

                        }


                        if(
                            !Number.isFinite(distanceKm) ||
                            distanceKm < 0
                        ){
                            distanceKm = 0;
                        }


                        distanceElement.textContent =
                            distanceKm.toFixed(2) +
                            " km";

                    }


                    // =================================================
                    // PATROL POINTS
                    // =================================================

const pointsElement =
    popupElement.querySelector(
        "#" +
        CSS.escape(
            "staffPatrolPoints_" + staffName
        )
    );

                    if(pointsElement){

                        pointsElement.textContent =
                            calculatedPointCount
                                .toLocaleString();

                    }


                    // =================================================
                    // LAST GPS UPDATE
                    // =================================================

const updatedAtElement =
    popupElement.querySelector(
        "#" +
        CSS.escape(
            "staffUpdatedAt_" + staffName
        )
    );

                    if(updatedAtElement){

                        const pointTime =
                            typeof getPointTime ===
                            "function"
                                ? Number(
                                    getPointTime(
                                        latestPoint
                                    )
                                  ) || 0
                                : Number(
                                    latestPoint.time || 0
                                  );


                        updatedAtElement.textContent =
                            pointTime > 0
                                ? new Date(
                                    pointTime
                                  ).toLocaleString()
                                : "Unknown";

                    }


// =================================================
// CURRENT GIS LOCATION
// =================================================

const currentLocationElement =
    popupElement.querySelector(
        "#" +
        CSS.escape(
            "staffCurrentLocation_" +
            popupKey
        )
    );


if(
    currentLocationElement &&
    typeof window.resolveCurrentGIS ===
        "function"
){

    try{

        const resolved =
            window.resolveCurrentGIS(
                lat,
                lon
            );


        if(
            resolved &&
            (
                resolved.compartment ||
                resolved.beat ||
                resolved.range ||
                resolved.division
            )
        ){

            currentLocationElement.innerHTML = `
                <div>
                    🌲 Compartment:
                    <b>
                        ${resolved.compartment || "N/A"}
                    </b>
                </div>

                <div>
                    🧭 Beat:
                    <b>
                        ${resolved.beat || "N/A"}
                    </b>
                </div>

                <div>
                    🏢 Range:
                    <b>
                        ${resolved.range || "N/A"}
                    </b>
                </div>
            `;

        }
        else if(
            resolved &&
            resolved.village
        ){

            currentLocationElement.innerHTML = `
                <div>
                    🏡 Village:
                    <b>
                        ${resolved.village}
                    </b>
                </div>
            `;

        }

    }catch(e){

        console.warn(
            "⚠ Patrol point GIS update failed:",
            staffName,
            e
        );

    }

}
                    // =================================================
                    // NAVIGATE BUTTON
                    // -------------------------------------------------
                    // Ensure navigation always uses latest point.
                    // =================================================

                    const buttons =
                        popupElement.querySelectorAll(
                            "button"
                        );


                    buttons.forEach(
                        function(button){

                            try{

                                const oldOnClick =
                                    button.getAttribute(
                                        "onclick"
                                    ) || "";


                                if(
                                    oldOnClick.indexOf(
                                        "navigateHEC"
                                    ) !== -1
                                ){

                                    button.setAttribute(
                                        "onclick",
                                        "navigateHEC('" +
                                        String(lat) +
                                        "','" +
                                        String(lon) +
                                        "')"
                                    );

                                }


                            }catch(e){}

                        }
                    );


                    // =================================================
                    // DIAGNOSTIC IDENTITY
                    // =================================================

                    popupElement.dataset.sessionId =
                        sessionId;


                    popupElement.dataset.pointId =
                        pointId;
                    window.StaffPopup.place(marker);


                }catch(error){

                    console.warn(
                        "⚠ Patrol popup refresh failed:",
                        staffName,
                        error
                    );

                }

            };


// ========================================================
// 17. POPUP LIVE REFRESH LIFECYCLE
// --------------------------------------------------------
// One authoritative refresh path.
//
// refreshPopup() already:
//   • re-resolves visibleStaffCache
//   • re-resolves the active sessionId
//   • reads the latest patrol point from sessionPointCache
//   • patches the EXISTING popup DOM
//   • updates GPS
//   • updates speed
//   • updates distance
//   • updates patrol-point count
//   • updates duty duration
//   • updates Last GPS Update
//   • updates GIS
//   • updates navigation coordinates
//
// IMPORTANT:
// - Do NOT recreate popup HTML while it is open.
// - Do NOT call setPopupContent() here.
// - Do NOT create another Firestore listener.
// - Do NOT read Firestore here.
// - Do NOT create another patrol_tracks listener.
//
// The timer exists ONLY while this popup is open.
// ========================================================


// ========================================================
// CLEAN UP ANY INVALID/OLD POPUP REFRESH TIMER
// --------------------------------------------------------
// updateLiveMarkerFromPatrolPoint() may execute many times.
// Never allow multiple timers for the same marker.
// ========================================================

if(
    marker.__ggPopupRefreshTimer &&
    typeof marker.__ggPopupRefreshTimer === "number" &&
    !marker.isPopupOpen()
){

    try{
        clearInterval(
            marker.__ggPopupRefreshTimer
        );
    }catch(e){}

    marker.__ggPopupRefreshTimer = null;
}


// ========================================================
// 17A. REFRESH IMMEDIATELY IF POPUP IS ALREADY OPEN
// ========================================================

if(
    typeof marker.isPopupOpen ===
    "function" &&
    marker.isPopupOpen()
){

    try{
        window.StaffPopup.deferRefresh(marker, refreshPopup);
    }catch(error){

        console.warn(
            "⚠ Patrol popup immediate refresh failed:",
            staffName,
            error
        );

    }

}


// ========================================================
// 18. REFRESH EVERY TIME POPUP OPENS
// --------------------------------------------------------
// One authoritative refresh path.
//
// When popup opens:
//   1. Refresh immediately.
//   2. Start ONE local DOM refresh timer.
//   3. Timer reads sessionPointCache through refreshPopup().
//   4. No Firestore read/listener is created.
//
// When popup closes:
//   1. Stop the timer.
//   2. Release the timer reference.
//
// This keeps the open popup live without replacing its DOM.
// ========================================================

if(
    marker.__ggLatestPopupHandlerBound !== true
){

    marker.__ggLatestPopupHandlerBound =
        true;


    // ====================================================
    // POPUP OPEN
    // ====================================================

    marker.on(
        "popupopen",
        function(){

            try{

                // --------------------------------------------
                // Immediate authoritative refresh
                // --------------------------------------------

                window.StaffPopup.deferRefresh(marker, refreshPopup);


                // --------------------------------------------
                // Prevent duplicate timers
                // --------------------------------------------

                if(
                    marker.__ggPopupRefreshTimer
                ){

                    try{
                        clearInterval(
                            marker.__ggPopupRefreshTimer
                        );
                    }catch(e){}

                    marker.__ggPopupRefreshTimer =
                        null;
                }


                // --------------------------------------------
                // Live popup DOM refresh
                // --------------------------------------------
                //
                // IMPORTANT:
                // This timer does NOT query Firestore.
                //
                // refreshPopup() obtains the latest point
                // from the existing authoritative
                // sessionPointCache.
                //
                // 1 second is intentional because:
                //   • Duty Duration is time dependent.
                //   • Last GPS Update must remain current.
                //   • GPS/speed/distance can change whenever
                //     the central patrol listener updates cache.
                //
                // The timer only exists while the popup
                // remains open.
                // --------------------------------------------

                marker.__ggPopupRefreshTimer =
                    setInterval(
                        function(){

                            try{

                                if(
                                    typeof marker.isPopupOpen !==
                                    "function" ||
                                    !marker.isPopupOpen()
                                ){

                                    try{
                                        clearInterval(
                                            marker.__ggPopupRefreshTimer
                                        );
                                    }catch(e){}

                                    marker.__ggPopupRefreshTimer =
                                        null;

                                    return;
                                }


                                // --------------------------------
                                // AUTHORITATIVE POPUP REFRESH
                                // --------------------------------

                                refreshPopup();


                                // --------------------------------
                                // If refreshPopup() closed the
                                // popup because staff/session is
                                // no longer valid, immediately
                                // release the timer.
                                // --------------------------------

                                if(
                                    typeof marker.isPopupOpen ===
                                    "function" &&
                                    !marker.isPopupOpen()
                                ){

                                    try{
                                        clearInterval(
                                            marker.__ggPopupRefreshTimer
                                        );
                                    }catch(e){}

                                    marker.__ggPopupRefreshTimer =
                                        null;
                                }

                            }catch(error){

                                console.warn(
                                    "⚠ Live popup refresh failed:",
                                    staffName,
                                    error
                                );

                            }

                        },
                        1000
                    );

            }catch(error){

                console.warn(
                    "⚠ Patrol popup-open refresh failed:",
                    staffName,
                    error
                );

            }

        }
    );


    // ====================================================
    // POPUP CLOSE
    // ----------------------------------------------------
    // Always stop the timer when the popup closes.
    // ====================================================

    marker.on(
        "popupclose",
        function(){
            window.StaffPopup.cancelRefresh(marker);

            try{

                if(
                    marker.__ggPopupRefreshTimer
                ){

                    clearInterval(
                        marker.__ggPopupRefreshTimer
                    );

                    marker.__ggPopupRefreshTimer =
                        null;
                }

            }catch(error){

                console.warn(
                    "⚠ Patrol popup timer cleanup failed:",
                    staffName,
                    error
                );

                marker.__ggPopupRefreshTimer =
                    null;
            }

        }
    );

}
    }catch(error){

        console.warn(
            "⚠ Patrol point marker update failed:",
            error
        );

    }

}

